<style lang="scss" src="./date-picker-modal.scss" scoped></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MonthOptions, WeekDayArray } from "../constants";
import Select from "../../components/select/select.vue";
import {
  format,
  startOfISOWeek,
  addDays,
  isSameMonth,
  isSameDay,
  isAfter,
  isBefore
} from "date-fns";
import Button from "../../components/button/button.vue";
import {
  ButtonMode,
  ButtonSize
} from "../../components/button/button.constants";

function getFirstDayOfWeek(day) {
  return startOfISOWeek(day);
}

function getDaysInAWeek(day) {
  const firstDay = getFirstDayOfWeek(day);
  const weekDays = [];

  for (let i = 0; i < 7; i++) {
    const day = addDays(firstDay, i);
    weekDays.push({
      label: `${day.getDate()}`,
      value: day
    });
  }

  return weekDays;
}

@Component({
  components: {
    Select,
    Button
  }
})
export default class DatePickerModal extends Vue {
  @Prop({
    type: Date
  })
  defaultStartDate;

  @Prop({
    type: Date
  })
  defaultEndDate;

  @Prop({
    type: Number,
    default: 1900
  })
  startYear;

  @Prop({
    type: Number,
    default: 2100
  })
  endYear;

  /**
   * {
   *  label: String,
   *  startDate: Date,
   *  endDate: Date
   * }
   */
  @Prop({
    type: Array,
    default: () => []
  })
  shortCuts;

  startDate = new Date();
  endDate = new Date();
  startMonth = new Date();
  endMonth = new Date();
  defaultStartMonth = 0;
  defaultStartYear = 1900;
  defaultEndMonth = 0;
  defaultEndYear = 2100;

  startMonthOptions = MonthOptions;
  endMonthOptions = MonthOptions;
  startYearOptions;
  endYearOptions;

  weekDays = WeekDayArray;
  yearOptions = [];
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  setStartDate = true;

  updateMonthRangeByDate() {
    let sy = this.startDate.getFullYear();
    let sm = this.startDate.getMonth();
    const ey = this.endDate.getFullYear();
    const em = this.endDate.getMonth();

    if (sy > ey) {
      if (em === 0) {
        sy = ey - 1;
        sm = 11;
      } else if (em > 0) {
        sy = ey;
        sm = em - 1;
      }
    } else if (sy === ey && sm >= em) {
      if (em === 0) {
        sy = ey - 1;
        sm = 11;
      } else if (em > 0) {
        sy = ey;
        sm = em - 1;
      }
    }

    this.startMonth = new Date(sy, sm, 1);
    this.endMonth = new Date(ey, em, 1);
    this.defaultStartMonth = sm;
    this.defaultStartYear = sy;
    this.defaultEndMonth = em;
    this.defaultEndYear = ey;

    if (sy === ey) {
      // Update month options
      this.startMonthOptions = MonthOptions.filter(m => m.value < em);
      this.endMonthOptions = MonthOptions.filter(m => m.value > sm);
    } else {
      this.startMonthOptions = MonthOptions;
      this.endMonthOptions = MonthOptions;
    }

    this.startYearOptions = this.yearOptions.filter(y => y.value <= ey);
    this.endYearOptions = this.yearOptions.filter(y => y.value >= sy);
  }

  updateMonthRangeByMonth() {
    let sy = this.startMonth.getFullYear();
    let sm = this.startMonth.getMonth();
    const ey = this.endMonth.getFullYear();
    const em = this.endMonth.getMonth();

    if (sy > ey) {
      if (em === 0) {
        sy = ey - 1;
        sm = 11;
      } else if (em > 0) {
        sy = ey;
        sm = em - 1;
      }
    } else if (sy === ey && sm >= em) {
      if (em === 0) {
        sy = ey - 1;
        sm = 11;
      } else if (em > 0) {
        sy = ey;
        sm = em - 1;
      }
    }

    this.startMonth = new Date(sy, sm, 1);
    this.endMonth = new Date(ey, em, 1);
    this.defaultStartMonth = sm;
    this.defaultStartYear = sy;
    this.defaultEndMonth = em;
    this.defaultEndYear = ey;

    if (sy === ey) {
      // Update month options
      this.startMonthOptions = MonthOptions.filter(m => m.value < em);
      this.endMonthOptions = MonthOptions.filter(m => m.value > sm);
    } else {
      this.startMonthOptions = MonthOptions;
      this.endMonthOptions = MonthOptions;
    }

    this.startYearOptions = this.yearOptions.filter(y => y.value <= ey);
    this.endYearOptions = this.yearOptions.filter(y => y.value >= sy);
  }

  beforeMount() {
    this.startDate = this.defaultStartDate || new Date();
    this.endDate = this.defaultEndDate || new Date();

    for (let i = this.startYear; i <= this.endYear; i++) {
      this.yearOptions.push({ label: `${i}`, value: i });
    }

    this.updateMonthRangeByDate();
  }

  dayInMonth(day, month) {
    return isSameMonth(day, month);
  }

  getWeekDays(startDay, i) {
    const day = addDays(startDay, (i - 1) * 7);
    return getDaysInAWeek(day);
  }

  handleClickShortCut(index) {
    const shortCut = this.shortCuts[index];
    this.startDate = shortCut.startDate;
    this.endDate = shortCut.endDate;
    this.updateMonthRangeByDate();
    this.$forceUpdate();
  }

  getDateString(date) {
    return `${format(date, "LLLL d, y")}`;
  }

  getStateClass(date, month) {
    if (!isSameMonth(date, month)) {
      return "DatePickerModal--inactive";
    }

    if (isSameDay(date, this.startDate)) {
      if (isSameDay(this.startDate, this.endDate)) {
        return "DatePickerModal--only";
      }

      return "DatePickerModal--start";
    }

    if (isSameDay(date, this.endDate)) {
      return "DatePickerModal--end";
    }

    if (isBefore(date, this.endDate) && isAfter(date, this.startDate)) {
      return "DatePickerModal--middle";
    }

    return "DatePickerModal--active";
  }

  handleStartMonthChange(value) {
    this.startMonth = new Date(this.startMonth.getFullYear(), value, 1);
    this.updateMonthRangeByMonth();
  }

  handleStartYearChange(value) {
    this.startMonth = new Date(value, this.startMonth.getMonth(), 1);
    this.updateMonthRangeByMonth();
  }

  handleEndMonthChange(value) {
    this.endMonth = new Date(this.endMonth.getFullYear(), value, 1);
    this.updateMonthRangeByMonth();
  }

  handleEndYearChange(value) {
    this.endMonth = new Date(value, this.endMonth.getMonth(), 1);
    this.updateMonthRangeByMonth();
  }

  handleDateClick(day, month) {
    if (isSameMonth(day.value, month)) {
      if (this.setStartDate) {
        this.startDate = day.value;
      } else {
        this.endDate = day.value;
      }

      this.setStartDate = !this.setStartDate;

      if (isBefore(this.endDate, this.startDate)) {
        this.endDate = this.startDate;
      }
    }
  }

  handleClose() {
    /**
     * emits when user click cancel
     *
     * @event close
     */
    this.$emit("close");
  }

  handleApply() {
    /**
     * emits when user click apply
     *
     * @event apply
     */
    this.$emit("apply", this.startDate, this.endDate);
  }
}
</script>

<template>
  <div class="DatePickerModal">
    <div class="DatePickerModal__Left">
      <div class="DatePickerModal__LeftContent">
        <div
          v-for="(item, index) in shortCuts"
          :key="index"
          class="DatePickerModal__ShortCut"
          @click="handleClickShortCut(index)"
        >
          {{ item.label }}
        </div>
      </div>
    </div>
    <div class="DatePickerModal__Right">
      <div class="DatePickerModal__RightUpper">
        <div class="DatePickerModal__Calendar">
          <div class="DatePickerModal__MonthPicker">
            <Select
              class="DatePickerModal__SelectionMenu"
              search
              label="Start Month"
              :key="defaultStartMonth"
              :value="defaultStartMonth"
              :items="startMonthOptions"
              @select="handleStartMonthChange"
            />
            <Select
              class="DatePickerModal__SelectionMenu"
              search
              label="Start Year"
              :key="defaultStartYear"
              :value="defaultStartYear"
              :items="startYearOptions"
              @select="handleStartYearChange"
            />
          </div>
          <div class="DatePickerModal__DatePicker">
            <div class="DatePickerModal__Row">
              <div
                v-for="(day, i) in weekDays"
                :key="i"
                :class="[
                  'DatePickerModal__Weekday',
                  'DatePickerModal__DayBlock'
                ]"
              >
                {{ day }}
              </div>
            </div>
            <div class="DatePickerModal__StartMonth">
              <div
                v-for="i in 5"
                :key="`${defaultStartMonth}_${i}`"
                class="DatePickerModal__Row"
              >
                <div
                  v-for="(day, index) in getWeekDays(startMonth, i)"
                  :key="index"
                  :class="[
                    getStateClass(day.value, startMonth),
                    'DatePickerModal__Day',
                    'DatePickerModal__DayBlock'
                  ]"
                  @click="handleDateClick(day, startMonth)"
                >
                  {{ day.label }}
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="DatePickerModal__MiddleLine" />
        <div class="DatePickerModal__Calendar">
          <div class="DatePickerModal__MonthPicker">
            <Select
              class="DatePickerModal__SelectionMenu"
              search
              label="End Month"
              :key="defaultEndMonth"
              :value="defaultEndMonth"
              :items="endMonthOptions"
              @select="handleEndMonthChange"
            />
            <Select
              class="DatePickerModal__SelectionMenu"
              search
              label="End Year"
              :key="defaultEndYear"
              :value="defaultEndYear"
              :items="endYearOptions"
              @select="handleEndYearChange"
            />
          </div>
          <div class="DatePickerModal__DatePicker">
            <div class="DatePickerModal__Row">
              <div
                v-for="(day, i) in weekDays"
                :key="i"
                :class="[
                  'DatePickerModal__Weekday',
                  'DatePickerModal__DayBlock'
                ]"
              >
                {{ day }}
              </div>
            </div>
            <div v-for="i in 5" :key="i" class="DatePickerModal__Row">
              <div
                v-for="day in getWeekDays(endMonth, i)"
                :key="day.label"
                :class="[
                  getStateClass(day.value, endMonth),
                  'DatePickerModal__Day',
                  'DatePickerModal__DayBlock'
                ]"
                @click="handleDateClick(day, endMonth)"
              >
                {{ day.label }}
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="DatePickerModal__RightLower">
        <div class="DatePickerModal__DateRange">
          <span>{{ getDateString(startDate) }}</span>
          <span class="DatePickerModal__Arrow">&nbsp;&nbsp;→&nbsp;&nbsp;</span>
          <span>{{ getDateString(endDate) }}</span>
        </div>
        <div class="DatePickerModal__Buttons">
          <Button
            class="DatePickerModal__Button"
            label="Cancel"
            :mode="ButtonMode.SUBTLE"
            :size="ButtonSize.MEDIUM"
            @click="handleClose"
          />
          <Button
            class="DatePickerModal__Button"
            label="Apply"
            :mode="ButtonMode.PRIMARY"
            :size="ButtonSize.MEDIUM"
            @click="handleApply"
          />
        </div>
      </div>
    </div>
  </div>
</template>
